sys_script_include.script:
var NewsFetcherAjax = Class.create();
NewsFetcherAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getNews: function() {
        var companyName = this.getParameter('sysparm_company_name');
        var apiKey = 'S1dIcJaB6_h75kivKUZXx_WyACYlIM9bJiBbc8hTNrFos5-P'; // Leave your existing key here

        try {
            var r = new sn_ws.RESTMessageV2('Currents News API', 'Default GET');
            r.setStringParameterNoEscape('company_name', companyName);
            r.setStringParameterNoEscape('api_key', apiKey);

            var response = r.execute();
            if (response.getStatusCode() === 200) {
                var parsedResponse = JSON.parse(response.getBody());
                var articles = parsedResponse.news || [];
                var formattedNews = [];
                for (var i = 0; i < articles.length && i < 3; i++) {
                    formattedNews.push({ title: articles[i].title, url: articles[i].url });
                }
                return JSON.stringify({ success: true, data: formattedNews });
            }
            return JSON.stringify({ success: false, message: 'API Error' });
        } catch(ex) {
            return JSON.stringify({ success: false, message: ex.message });
        }
    },

    // --- NEW STOCK FUNCTION ---
    getStock: function() {
        var ticker = this.getParameter('sysparm_ticker');
        var apiKey = 'ql5SGIrPCxYbaA2diDEbuspaouXzvWoONtoCTdrl'; 

        try {
            var r = new sn_ws.RESTMessageV2('API Ninjas Stock', 'Default GET');
            r.setStringParameterNoEscape('ticker', ticker);
            r.setStringParameterNoEscape('api_key', apiKey);

            var response = r.execute();
            if (response.getStatusCode() === 200) {
                var data = JSON.parse(response.getBody());
                // API Ninjas returns price and currency
                if (data && data.price) {
                    return JSON.stringify({ success: true, price: data.price, name: data.name });
                }
            }
            return JSON.stringify({ success: false });
        } catch(ex) {
            return JSON.stringify({ success: false });
        }
    },

    type: 'NewsFetcherAjax'
});
